function HasCloseElements(numbers: array of real; threshold: real): boolean;
begin
  for var i := 0 to numbers.Length - 2 do
    for var j := i + 1 to numbers.Length - 1 do
      if Abs(numbers[i] - numbers[j]) < threshold then
      begin
        Result := True;
        exit;
      end;
  Result := False;
end;


function SeparateParenGroups(parenString: string): array of string;
begin
  var stack := new Stack<char>;
  var tempString := parenString.Replace(' ', '');
  var tempResult := new List<string>;
  var start := 0;
  var length := tempString.Length;

  for var i := 0 to length - 1 do
  begin
    if tempString[i] = '(' then
      stack.Push(tempString[i])
    else if stack.Count > 0 then
      stack.Pop;

    if (stack.Count = 0) and (i = length - 1) then
    begin
      tempResult.Add(tempString.Substring(start, i - start + 1));
      start := i + 1;
    end;
  end;

  Result := tempResult.ToArray;
end;


