function ParseNestedParens(parenString: string): array of integer;
begin
  var groups := parenString.Split(' ');
  var results := new List<integer>;

  foreach var group in groups do
  begin
    var maxDepth := 0;
    var currentDepth := 0;

    for var i := 1 to group.Length do
    begin
      if group[i] = '(' then
        currentDepth += 1
      else if group[i] = ')' then
        currentDepth -= 1;

      if currentDepth > maxDepth then
        maxDepth := currentDepth;
    end;

    results.Add(maxDepth);
  end;

  Result := results.ToArray;
end;


