function MakePalindrome(str: string): string;
begin
  var n := str.Length;
  var postfix := '';
  var prefix := '';

  for var i := n - 1 downto 0 do
  begin
    postfix := str[i] + postfix;
    prefix := str.Substring(0, i);

    if IsPalindrome(prefix) then
      break;
  end;

  var suffix := ReverseString(postfix);
  Result := str + suffix;
end;


