  var maxVal := numbers.Max;
  var scale := maxVal - minVal;
  var translate := minVal;
  var rescaled := new real[numbers.Length];
  for var i := 0 to numbers.Length - 1 do
    rescaled[i] := (numbers[i] - minVal) / scale;
  Result := rescaled;
end;


