function Factorize(n: integer): array of integer;
begin
  var i := 2;
  var num := n;
  var primes := new List<integer>;
  var num2 := n;
  while i * i <= n do
  begin
    if num mod i = 0 then
    begin
      primes.Add(i);
      num := num div i;
    end
    else
      i += 1;
  end;
  if num > 1 then
    primes.Add(num);

  var freqs := new Dictionary<integer, integer>;
  foreach var prime in primes do
    freqs[prime] := 0;

  var numList := primes.ToList;
  while num <> n do
  begin
    for var j := 0 to numList.Count - 1 do
    begin
      if num <> n then
      begin
        freqs[numList[j]] += 1;
        num := num * numList[j];
      end;
    end;
  end;

  var res := new List<integer>;
  foreach var pair in freqs do
    for var j := 1 to pair.Value do
      res.Add(pair.Key);

  Result := res.ToArray;
end;


