function Poly(xs : array of real; x : real): real;
{ Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n }
begin
  var _result := 0.0;
  for var i := 0 to xs.Length - 1 do
    _result := _result + xs[i] * Power(x, i);
  Result := _result;
end;
function FindZero(xs: array of real): real;
begin
  var n := xs.Length;
  if n mod 2 <> 0 then
    raise new System.ArgumentException('FindZero: xs must have even number of coefficients');

  var maxcoef := xs.Max;
  if maxcoef = 0 then
  begin
    Result := 0;
    exit;
  end;

  var (a, b) := (xs[0], xs[1]);
  var x := (a - b) / (2 * maxcoef);
  var eps := 1e-10;

  while abs(x - a) > eps do
  begin
    a := b;
    b := x;
    x := (a - b) / (2 * maxcoef);
  end;

  Result := x;
end;


