  var c0 := new Dictionary<char, integer>;
  var c1 := new Dictionary<char, integer>;
  foreach var ch in s0 do
    if c0.ContainsKey(ch) then
      c0[ch] += 1
    else
      c0[ch] := 1;
  foreach var ch in s1 do
    if c1.ContainsKey(ch) then
      c1[ch] += 1
    else
      c1[ch] := 1;
  foreach var kv in c0 do
    if not c1.ContainsKey(kv.Key) or (c1[kv.Key] < kv.Value) then
    begin
      Result := False;
      exit;
    end;
  foreach var kv in c1 do
    if not c0.ContainsKey(kv.Key) or (c0[kv.Key] < kv.Value) then
    begin
      Result := False;
      exit;
    end;
  Result := True;
end;


