  var temp := lst.ToArray;
  var sorted := temp.OrderBy(x -> x).ToArray;
  var resultList := new List<integer>;
  var left := 0;
  var right := sorted.Length - 1;

  while left <= right do
  begin
    if left <= right then
    begin
      resultList.Add(sorted[left]);
      left += 1;
    end;

    if left <= right then
    begin
      resultList.Add(sorted[right]);
      right -= 1;
    end;
  end;

  Result := resultList.ToArray;
end;


function TriangleArea(a, b, c: real): real;
