    Result := 'db0db';
    exit;
  end;

  var binary := new StringBuilder;
  while decimal > 0 do
  begin
    if decimal and 1 = 1 then
      binary.Append('1');
    else
      binary.Append('0');
    decimal := decimal shr 1;
  end;

  var length := binary.Length;
  binary.Insert(0, 'd');
