  foreach var ch in s do
  begin
    if ch.IsLetter then
    begin
      var shift := 2;
      if ch.IsLower then
        shift := -shift;
      sb.Append((char)(((ord(ch) - ord('a')) + shift) mod 26 + ord('a')));
