    begin
      if ch.IsLower then
        sb.Append(ch.ToUpper)
      else
        sb.Append(ch.ToLower);
    end
    else
      sb.Append(ch);
  end;
  var s := sb.ToString;
  var vowels := new HashSet<char>('aeiou'.ToCharArray);
  var sb2 := new StringBuilder;
  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    if ch.IsLetter then
    begin
      if s[i].IsLower then
        sb2.Append(ch.ToUpper)
      else
        sb2.Append(ch.ToLower);
      if vowels.Contains(s[i]) then
      begin
        var pos := sb2.Length;
        if s[i].IsLower then
          sb2.Append(Chr(Ord('a') + (pos + 2) mod 26))
        else
          sb2.Append(Chr(Ord('A') + (pos + 2) mod 26));
      end;
    end
    else
      sb2.Append(ch);
  end;
  Result := sb2.ToString;
end;


