function GetClosestVowel(word: string): string;
begin
  var vowels := HSet('a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U');
  var left := 0;
  var right := word.Length - 1;
  while left < right do
  begin
    while (left < right) and not vowels.Contains(word[left + 1]) do
      left += 1;
    while (left < right) and not vowels.Contains(word[right - 1]) do
      right -= 1;
    if (left < right) then
    begin
      if (word[left + 1] <> word[right - 1]) and vowels.Contains(word[left + 1]) and 
         vowels.Contains(word[right - 1]) then
      begin
        Result := word[left + 1];
        exit;
      end;
    end;
    left += 1;
    right -= 1;
  end;
  Result := '';
end;


function MatchParens(lst: array of string): string;
begin
  var s1 := lst[0];
  var s2 := lst[1];
  var stack1 := new Stack<char>;
  var stack2 := new Stack<char>;

  for var i := 1 to s1.Length do
    stack1.Push(s1[i]);

  for var i := 1 to s2.Length do
    stack2.Push(s2[i]);

  while (stack1.Count > 0) and (stack2.Count > 0) do
  begin
    var ch1 := stack1.Pop;
    var ch2 := stack2.Pop;

    if (ch1 <> ch2) and (ch1 <> ')') and (ch2 <> '(') then
    begin
      Result := 'No';
      exit;
    end;
  end;

  if (stack1.Count > 0) or (stack2.Count > 0) then
    Result := 'No'
  else
    Result := 'Yes';
end;


