function EvenOddCount(num: integer): (integer, integer);
begin
  var evenCount := 0;
  var oddCount := 0;
  var absNum := Abs(num);

  while absNum > 0 do
  begin
    var digit := absNum mod 10;
    if digit mod 2 = 0 then
      evenCount += 1;
    else
      oddCount += 1;
    absNum := absNum div 10;
  end;

  Result := (evenCount, oddCount);
end;


function IntToMiniRoman(number: integer): string;
begin
  if (number < 1) or (number > 1000) then
    raise new System.ArgumentException('Number must be between 1 and 1000');

  var values := |1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1|;
  var symbols := |'m', 'cm', 'd', 'cd', 'c', 'xc', 'l', 'xl', 'x', 'ix', 'v', 'iv', 'i'|;

  var roman := new StringBuilder;
  var remaining := number;

  for var i := 0 to values.Length - 1 do
  begin
    while remaining >= values[i] do
    begin
      roman.Append(symbols[i]);
      remaining -= values[i];
    end;
  end;

  Result := roman.ToString.ToLower;
end;


