function Solve(s: string): string;
begin
  var letters := new List<char>;
  foreach var ch in s do
    if char.IsLetter(ch) then
      letters.Add(ch);

  if letters.Count = 0 then
    Result := s.Reverse.JoinToString('')
  else
  begin
    var sb := new StringBuilder;
    foreach var ch in s do
      if char.IsLetter(ch) then
        if char.IsLower(ch) then
          sb.Append(char.ToUpper(ch))
        else
          sb.Append(char.ToLower(ch));
    Result := sb.ToString;
  end;
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
    Result := nil
  else
    Result := System.Security.Cryptography.MD5.Create().ComputeHash(Encoding.UTF8.GetBytes(text)).HashToString;
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  var evenDigits := new List<integer>;
  for var num := a to b do
    if (num mod 2 = 0) and (num <> 0) then
      evenDigits.Add(num);
  Result := evenDigits.ToArray;
end;
